// apt-index.mjs — the runtime *.index.bin generator must produce byte-identical
// output to the upstream script (renderer/src/assets/make-index-files.mjs),
// because assets/data reads the ndjson THROUGH these offset tables. The shipped
// bins in renderer/public/data/en were generated by the upstream script, so a
// byte-compare against them is a full-fidelity drift guard.
import { test } from 'node:test'
import assert from 'node:assert/strict'
import { readFile } from 'node:fs/promises'
import { buildIndexBins, fnv1a32 } from './apt-index.mjs'

const EN_DIR = new URL('../../renderer/public/data/en/', import.meta.url)

test('fnv1a32 matches @sindresorhus/fnv1a size-32 on known vectors', () => {
  // Independent reference values for FNV-1a 32-bit over UTF-8.
  assert.equal(fnv1a32(''), 0x811c9dc5)
  assert.equal(fnv1a32('a'), 0xe40c292c)
  assert.equal(fnv1a32('foobar'), 0xbf9cf968)
  // non-ASCII goes through UTF-8 bytes, not code units
  assert.equal(fnv1a32('ä'), fnv1a32('ä'))
  assert.notEqual(fnv1a32('ä'), fnv1a32('a'))
})

test('generated index bins are byte-identical to the shipped ones', async () => {
  const itemsNdjson = await readFile(new URL('items.ndjson', EN_DIR), 'utf8')
  const statsNdjson = await readFile(new URL('stats.ndjson', EN_DIR), 'utf8')
  const bins = buildIndexBins({ itemsNdjson, statsNdjson })
  for (const name of ['stats-ref.index.bin', 'stats-matcher.index.bin', 'items-name.index.bin', 'items-ref.index.bin']) {
    const shipped = await readFile(new URL(name, EN_DIR))
    const mine = Buffer.from(bins[name].buffer, bins[name].byteOffset, bins[name].byteLength)
    assert.ok(shipped.equals(mine), `${name} differs from the upstream-generated file`)
  }
})
